package agent

import (
	"fmt"

	"github.com/Infisical/infisical-agent-injector/pkg/util"
	corev1 "k8s.io/api/core/v1"
)

func (a *Agent) ContainerSidecar() (corev1.Container, error) {
	volumeMounts := []corev1.VolumeMount{}

	if !a.isWindows {
		volumeMounts = append(volumeMounts, corev1.VolumeMount{
			Name:      a.serviceAccountTokenVolume.Name,
			MountPath: a.serviceAccountTokenVolume.MountPath,
			ReadOnly:  true,
		})
	}

	// This will add the secret volume mounts
	volumeMounts = append(volumeMounts, a.ContainerVolumeMounts(volumeMounts)...)

	script, envVars, err := util.BuildAgentScript(*a.configMap, false, a.isWindows, a.injectMode, a.cachingEnabled, a.pod.Annotations)
	if err != nil {
		return corev1.Container{}, fmt.Errorf("failed to build agent script: %w", err)
	}

	resources, err := a.ResourceRequirements()
	if err != nil {
		return corev1.Container{}, fmt.Errorf("failed to get resource requirements: %w", err)
	}
	lifecycle := a.Lifecycle()

	securityContext, err := a.SecurityContext()
	if err != nil {
		return corev1.Container{}, fmt.Errorf("failed to get security context: %w", err)
	}

	command := []string{"/bin/sh", "-ec"}
	if a.isWindows {
		command = []string{"pwsh.exe", "-Command"}
	}

	newContainer := corev1.Container{
		Name:         util.SidecarContainerName,
		Image:        a.agentImage,
		Resources:    resources,
		VolumeMounts: volumeMounts,
		Lifecycle:    &lifecycle,
		Command:      command,
		Args:         []string{script},
		Env:          envVars,
	}

	if securityContext != nil {
		newContainer.SecurityContext = securityContext
	}

	return newContainer, nil
}

package agent

import (
	"encoding/json"
	"fmt"
	"log"
	"slices"
	"strings"

	"github.com/Infisical/infisical-agent-injector/pkg/util"
	"github.com/Infisical/infisical-agent-injector/pkg/util/path"
	jsonpatch "github.com/evanphx/json-patch"
	corev1 "k8s.io/api/core/v1"
	"k8s.io/apimachinery/pkg/api/resource"
	"k8s.io/utils/pointer"
)

type Agent struct {
	pod                       *corev1.Pod
	configMap                 *util.ConfigMap
	serviceAccountTokenVolume *ServiceAccountTokenVolume
	injectMode                string
	cachingEnabled            bool
	agentImage                string
	isWindows                 bool
}

func NewAgent(pod *corev1.Pod, configMap *util.ConfigMap) (*Agent, error) {

	if configMap == nil {
		return nil, fmt.Errorf("config map is required")
	}

	injectMode := pod.Annotations[util.InjectModeAnnotation]
	if injectMode == "" {
		injectMode = util.InjectModeInit
	}

	cachingEnabled := pod.Annotations[util.AnnotationCachingEnabled] == "true"

	serviceAccountTokenVolume, err := getServiceAccountTokenVolume(pod)
	if err != nil {
		return nil, err
	}

	if configMap.Infisical.Address == "" {
		configMap.Infisical.Address = "https://app.infisical.com"
	}

	if len(configMap.Templates) == 0 {
		return nil, fmt.Errorf("no templates found in config map")
	}
	templateCount := len(configMap.Templates)
	for i, template := range configMap.Templates {
		if template.DestinationPath == "" {
			if templateCount > 1 {
				configMap.Templates[i].DestinationPath = fmt.Sprintf("%s-%d", util.DefaultDestinationPath, i+1)
			} else {
				configMap.Templates[i].DestinationPath = util.DefaultDestinationPath
			}
		}
	}

	agentImage := pod.Annotations[util.AnnotationAgentImage]
	isWindows := util.IsWindowsPod(pod)
	if agentImage == "" {

		if isWindows {
			agentImage = util.DefaultWindowsContainerImage
		} else {
			agentImage = util.DefaultLinuxContainerImage
		}
	}

	return &Agent{
		pod:                       pod,
		configMap:                 configMap,
		serviceAccountTokenVolume: serviceAccountTokenVolume,
		injectMode:                injectMode,
		cachingEnabled:            cachingEnabled,
		agentImage:                agentImage,
		isWindows:                 isWindows,
	}, nil
}

func (a *Agent) ContainerVolumeMounts(existingMounts []corev1.VolumeMount) []corev1.VolumeMount {
	volumeMounts := []corev1.VolumeMount{}

	mountPath := util.LinuxContainerWorkDirVolumeMountPath
	if a.isWindows {
		mountPath = util.WindowsContainerWorkDirVolumeMountPath
	}

	if !slices.ContainsFunc(existingMounts, func(mount corev1.VolumeMount) bool {
		return mount.MountPath == mountPath && mount.Name == util.ContainerWorkDirMountName
	}) {

		// we mount this on the users pod
		volumeMounts = append(volumeMounts, corev1.VolumeMount{
			Name:      util.ContainerWorkDirMountName,
			MountPath: mountPath,
		})
	}

	templateCount := len(a.configMap.Templates)

	for i, template := range a.configMap.Templates {

		destinationPath := path.Dir(template.DestinationPath, a.isWindows)

		var name string
		if templateCount > 1 {
			name = fmt.Sprintf("infisical-secrets-%d", i+1)
		} else {
			name = "infisical-secrets"
		}

		alreadyExists := false

		for _, volumeMount := range existingMounts {
			if volumeMount.MountPath == destinationPath {
				alreadyExists = true
				break
			}
		}

		if !alreadyExists {
			for _, volumeMount := range volumeMounts {
				if volumeMount.MountPath == destinationPath {
					alreadyExists = true
					break
				}
			}
		}

		if alreadyExists {
			log.Printf("volume mount %s already exists at %s. skipping creation.", name, destinationPath)
			continue
		}

		log.Printf("adding volume mount %s to %s", name, destinationPath)

		volumeMounts = append(volumeMounts, corev1.VolumeMount{
			Name:      name,
			MountPath: destinationPath,
			ReadOnly:  false,
		})
	}
	return volumeMounts
}

func (a *Agent) ValidateConfigMap() error {
	if err := util.ValidateInjectMode(a.injectMode); err != nil {
		return err
	}

	// check that the config map has a valid auth config
	if a.configMap.Infisical.Auth.Type == "" {
		return fmt.Errorf("auth type is required")
	}

	if a.configMap.Infisical.Auth.Type != util.KubernetesAuthType && a.configMap.Infisical.Auth.Type != util.LdapAuthType && a.configMap.Infisical.Auth.Type != util.AwsIamAuthType {
		return fmt.Errorf("auth type %s not supported. please use %s, %s, or %s", a.configMap.Infisical.Auth.Type, util.KubernetesAuthType, util.LdapAuthType, util.AwsIamAuthType)
	}

	// redundant if statement check, but will make sense when we add more authentication methods
	if a.configMap.Infisical.Auth.Type == util.KubernetesAuthType {

		if a.serviceAccountTokenVolume == nil {
			return fmt.Errorf("service account token volume is required")
		}

		if a.serviceAccountTokenVolume.Name == "" {
			return fmt.Errorf("service account token volume name is required")
		}

		if a.serviceAccountTokenVolume.MountPath == "" {
			return fmt.Errorf("service account token volume mount path is required")
		}

		if a.serviceAccountTokenVolume.TokenPath == "" {
			return fmt.Errorf("service account token volume token path is required")
		}
	}

	delimiter := "/"
	examplePath := "/path/to/destination/secret-file"
	if a.isWindows {
		delimiter = "\\"
		examplePath = "C:\\path\\to\\destination\\secret-file"
	}

	for _, template := range a.configMap.Templates {

		if template.DestinationPath == "" {
			return fmt.Errorf("template destination path is required")
		}

		// validates drive letter paths and UNC paths
		if !path.IsAbs(template.DestinationPath, a.isWindows) {
			return fmt.Errorf("template destination path must be an absolute path (e.g. %s)", examplePath)
		}

		slashCount := strings.Count(template.DestinationPath, delimiter)
		if slashCount < 2 {
			return fmt.Errorf("template destination path must be a folder (e.g. %s)", examplePath)
		}
	}

	return nil

}

func (a *Agent) PatchPod() ([]byte, error) {
	var podPatches jsonpatch.Patch

	// 1. add volume mounts that will hold the secrets
	for i, container := range a.pod.Spec.Containers {
		podPatches = append(podPatches, addVolumeMounts(
			container.VolumeMounts,
			a.ContainerVolumeMounts(container.VolumeMounts),
			fmt.Sprintf("/spec/containers/%d/volumeMounts", i))...)
	}

	if err := util.ValidateInjectMode(a.injectMode); err != nil {
		return nil, err
	}

	var requiredVolumes []corev1.Volume

	requiredVolumes = append(requiredVolumes, corev1.Volume{
		Name: util.ContainerWorkDirMountName,
		VolumeSource: corev1.VolumeSource{
			EmptyDir: &corev1.EmptyDirVolumeSource{},
		},
	})

	templateCount := len(a.configMap.Templates)
	for i := range a.configMap.Templates {
		var name string
		if templateCount > 1 {
			name = fmt.Sprintf("infisical-secrets-%d", i+1)
		} else {
			name = "infisical-secrets"
		}
		requiredVolumes = append(requiredVolumes, corev1.Volume{
			Name: name,
			VolumeSource: corev1.VolumeSource{
				EmptyDir: &corev1.EmptyDirVolumeSource{},
			},
		})
	}

	podPatches = append(podPatches, addVolumes(
		a.pod.Spec.Volumes,
		requiredVolumes,
		"/spec/volumes")...)

	switch a.injectMode {
	case util.InjectModeInit:
		err := a.appendInitContainer(&podPatches)
		if err != nil {
			return nil, err
		}
	case util.InjectModeSidecar:
		err := a.appendSidecarContainer(&podPatches)
		if err != nil {
			return nil, err
		}
	case util.InjectModeSidecarInit:
		err := a.appendInitContainer(&podPatches)
		if err != nil {
			return nil, err
		}

		err = a.appendSidecarContainer(&podPatches)
		if err != nil {
			return nil, err
		}
	}

	podPatches = append(podPatches, updatePodAnnotations(
		a.pod.Annotations,
		map[string]string{util.AnnotationAgentStatus: "injected"})...)

	if len(podPatches) > 0 {
		return json.Marshal(podPatches)
	}
	return nil, nil

}

func (a *Agent) Lifecycle() corev1.Lifecycle {

	// No preStop needed - k8s will send SIGTERM automatically
	// k8s sends the sigterm to PID 1, so in the startup script we forward the signal to the agent process (see linux-container-startup.sh.tmpl)

	return corev1.Lifecycle{}
}

func (a *Agent) appendInitContainer(podPatches *jsonpatch.Patch) error {
	container, err := a.ContainerInitSidecar()
	if err != nil {
		return err
	}

	if len(a.pod.Spec.InitContainers) != 0 {
		*podPatches = append(*podPatches, removeContainers("/spec/initContainers")...)
	}

	containers := append([]corev1.Container{container}, a.pod.Spec.InitContainers...)

	*podPatches = append(*podPatches, addContainers(
		[]corev1.Container{},
		containers,
		"/spec/initContainers")...)

	for i, container := range containers {
		if container.Name == util.InitContainerName {
			continue
		}
		*podPatches = append(*podPatches, addVolumeMounts(
			container.VolumeMounts,
			a.ContainerVolumeMounts(container.VolumeMounts),
			fmt.Sprintf("/spec/initContainers/%d/volumeMounts", i))...)
	}
	return nil
}

func (a *Agent) appendSidecarContainer(podPatches *jsonpatch.Patch) error {
	container, err := a.ContainerSidecar()
	if err != nil {
		return err
	}
	*podPatches = append(*podPatches, addContainers(
		a.pod.Spec.Containers,
		[]corev1.Container{container},
		"/spec/containers")...)
	return nil
}

func (a *Agent) ResourceRequirements() (corev1.ResourceRequirements, error) {

	const (
		// CPU, Linux
		DefaultCPULimitLinux   = "500m"
		DefaultCPURequestLinux = "100m"

		// Memory, Linux
		DefaultMemoryLimitLinux   = "128Mi"
		DefaultMemoryRequestLinux = "64Mi"

		// CPU, Windows
		DefaultCPULimitWindows   = "500m"
		DefaultCPURequestWindows = "100m"

		// Memory, Windows
		DefaultMemoryLimitWindows   = "512Mi"
		DefaultMemoryRequestWindows = "256Mi"
	)

	limits := corev1.ResourceList{}
	requests := corev1.ResourceList{}

	var cpuLimit, cpuRequest resource.Quantity
	var memoryLimit, memoryRequest resource.Quantity

	// we don't set defaults for ephemeral storage as it first became generally available in k8s 1.25.
	// additionally we want to let the cluster dictacte the pods ephemeral storage limits if not explicitly provided by the user.
	var ephemeralLimit, ephemeralRequest resource.Quantity
	var ephemeralLimitSet, ephemeralRequestSet bool

	// default limits
	if a.isWindows {
		// windows pods need much more memory than linux pods (this resolves out of memory restarts)
		memoryLimit, _ = resource.ParseQuantity(DefaultMemoryLimitWindows)     // 4x more
		memoryRequest, _ = resource.ParseQuantity(DefaultMemoryRequestWindows) // 2x more
		cpuLimit, _ = resource.ParseQuantity(DefaultCPULimitWindows)
		cpuRequest, _ = resource.ParseQuantity(DefaultCPURequestWindows)
	} else {
		memoryLimit, _ = resource.ParseQuantity(DefaultMemoryLimitLinux)
		memoryRequest, _ = resource.ParseQuantity(DefaultMemoryRequestLinux)
		cpuLimit, _ = resource.ParseQuantity(DefaultCPULimitLinux)
		cpuRequest, _ = resource.ParseQuantity(DefaultCPURequestLinux)
	}

	// user-defined ephemeral storage limits
	if a.pod.Annotations[util.AnnotationLimitsEphemeral] != "" {
		limit, err := resource.ParseQuantity(a.pod.Annotations[util.AnnotationLimitsEphemeral])
		if err != nil {
			return corev1.ResourceRequirements{}, fmt.Errorf("failed to parse ephemeral limit: %w", err)
		}
		ephemeralLimit = limit
		ephemeralLimitSet = true
	}

	// user-defined ephemeral storage requests
	if a.pod.Annotations[util.AnnotationRequestsEphemeral] != "" {
		request, err := resource.ParseQuantity(a.pod.Annotations[util.AnnotationRequestsEphemeral])
		if err != nil {
			return corev1.ResourceRequirements{}, fmt.Errorf("failed to parse ephemeral request: %w", err)
		}
		ephemeralRequest = request
		ephemeralRequestSet = true
	}

	// user-defined CPU limits
	if a.pod.Annotations[util.AnnotationLimitsCPU] != "" {
		limit, err := resource.ParseQuantity(a.pod.Annotations[util.AnnotationLimitsCPU])
		if err != nil {
			return corev1.ResourceRequirements{}, fmt.Errorf("failed to parse cpu limit: %w", err)
		}
		cpuLimit = limit
	}

	// user-defined CPU requests
	if a.pod.Annotations[util.AnnotationRequestsCPU] != "" {
		request, err := resource.ParseQuantity(a.pod.Annotations[util.AnnotationRequestsCPU])
		if err != nil {
			return corev1.ResourceRequirements{}, fmt.Errorf("failed to parse cpu request: %w", err)
		}
		cpuRequest = request
	}

	// user-defined memory limits
	if a.pod.Annotations[util.AnnotationLimitsMemory] != "" {
		limit, err := resource.ParseQuantity(a.pod.Annotations[util.AnnotationLimitsMemory])
		if err != nil {
			return corev1.ResourceRequirements{}, fmt.Errorf("failed to parse memory limit: %w", err)
		}
		memoryLimit = limit
	}

	// user-defined memory requests
	if a.pod.Annotations[util.AnnotationRequestsMemory] != "" {
		request, err := resource.ParseQuantity(a.pod.Annotations[util.AnnotationRequestsMemory])
		if err != nil {
			return corev1.ResourceRequirements{}, fmt.Errorf("failed to parse memory request: %w", err)
		}
		memoryRequest = request
	}

	limits[corev1.ResourceCPU] = cpuLimit
	limits[corev1.ResourceMemory] = memoryLimit
	if ephemeralLimitSet {
		limits[corev1.ResourceEphemeralStorage] = ephemeralLimit
	}

	requests[corev1.ResourceCPU] = cpuRequest
	requests[corev1.ResourceMemory] = memoryRequest
	if ephemeralRequestSet {
		requests[corev1.ResourceEphemeralStorage] = ephemeralRequest
	}

	// set the limits and requests on the resource requirements

	resources := corev1.ResourceRequirements{
		Limits:   limits,
		Requests: requests,
	}

	return resources, nil
}

func (a *Agent) SecurityContext() (*corev1.SecurityContext, error) {

	setSecurityContext, err := util.ParseStringToBool(a.pod.Annotations[util.AnnotationSetSecurityContext], false)
	if err != nil {
		return nil, fmt.Errorf("failed to parse set security context annotation: %w", err)
	}

	if !setSecurityContext {
		return nil, nil
	}

	readOnlyRootFilesystem, err := util.ParseStringToBool(a.pod.Annotations[util.AnnotationSecurityContextReadOnlyRootFilesystem], true)
	if err != nil {
		return nil, fmt.Errorf("failed to parse security context read only root filesystem annotation: %w", err)
	}

	runAsUser, err := util.ParseStringToInt(a.pod.Annotations[util.AnnotationSecurityContextRunAsUser], 1000)
	if err != nil {
		return nil, fmt.Errorf("failed to parse security context run as user: %w", err)
	}

	runAsGroup, err := util.ParseStringToInt(a.pod.Annotations[util.AnnotationSecurityContextRunAsGroup], 2000)
	if err != nil {
		return nil, fmt.Errorf("failed to parse security context run as group: %w", err)
	}

	runAsNonRoot := true

	// if any of these are true, we run as root
	// we default to non-root if not explicitly set
	if runAsUser == 0 || runAsGroup == 0 {
		runAsNonRoot = false
	}

	securityContext := &corev1.SecurityContext{
		RunAsUser:    pointer.Int64(int64(runAsUser)),
		RunAsGroup:   pointer.Int64(int64(runAsGroup)),
		RunAsNonRoot: pointer.Bool(runAsNonRoot),
		Capabilities: &corev1.Capabilities{
			Drop: []corev1.Capability{"ALL"},
		},
		Privileged:               pointer.Bool(false),
		AllowPrivilegeEscalation: pointer.Bool(false),
	}

	if !a.isWindows {
		// cannot be set on windows pods
		securityContext.ReadOnlyRootFilesystem = pointer.Bool(readOnlyRootFilesystem)
	}

	return securityContext, nil

}

package agent

import (
	"fmt"

	"github.com/Infisical/infisical-agent-injector/pkg/util"
	corev1 "k8s.io/api/core/v1"
)

func (a *Agent) ContainerInitSidecar() (corev1.Container, error) {
	volumeMounts := []corev1.VolumeMount{}

	if !a.isWindows {
		volumeMounts = append(volumeMounts, corev1.VolumeMount{
			Name:      a.serviceAccountTokenVolume.Name,
			MountPath: a.serviceAccountTokenVolume.MountPath,
			ReadOnly:  true,
		})
	}

	volumeMounts = append(volumeMounts, a.ContainerVolumeMounts(volumeMounts)...)

	script, envVars, err := util.BuildAgentScript(*a.configMap, true, a.isWindows, a.injectMode, a.cachingEnabled, a.pod.Annotations)
	if err != nil {
		return corev1.Container{}, fmt.Errorf("failed to build agent script: %w", err)
	}

	resources, err := a.ResourceRequirements()
	if err != nil {
		return corev1.Container{}, fmt.Errorf("failed to get resource requirements: %w", err)
	}

	securityContext, err := a.SecurityContext()
	if err != nil {
		return corev1.Container{}, fmt.Errorf("failed to get security context: %w", err)
	}

	command := []string{"/bin/sh", "-c"}
	if a.isWindows {
		command = []string{"pwsh.exe", "-Command"}
	}

	newContainer := corev1.Container{
		Name:         util.InitContainerName,
		Image:        a.agentImage,
		Resources:    resources,
		VolumeMounts: volumeMounts,
		Command:      command,
		Env:          envVars,
		Args:         []string{script},
	}

	if securityContext != nil {
		newContainer.SecurityContext = securityContext
	}

	return newContainer, nil

}

package util

type InfisicalConfig struct {
	Address                     string       `yaml:"address"`
	ExitAfterAuth               bool         `yaml:"exit-after-auth"`
	RevokeCredentialsOnShutdown bool         `yaml:"revoke-credentials-on-shutdown"`
	RetryConfig                 *RetryConfig `yaml:"retry-strategy,omitempty"`
}

type Template struct {
	SourcePath            string `yaml:"source-path"`
	Base64TemplateContent string `yaml:"base64-template-content"`
	DestinationPath       string `yaml:"destination-path"`
	TemplateContent       string `yaml:"template-content"`

	Config struct { // Configurations for the template
		PollingInterval string `yaml:"polling-interval"` // How often to poll for changes in the secret
	} `yaml:"config"`
}

type AuthConfig struct {
	Type string `yaml:"type"`
}

type Sink struct {
	Type   string      `yaml:"type"`
	Config SinkDetails `yaml:"config"`
}

type SinkDetails struct {
	Path string `yaml:"path"`
}

type PersistentCacheConfig struct {
	Type                    string `yaml:"type"`
	ServiceAccountTokenPath string `yaml:"service-account-token-path"`
	Path                    string `yaml:"path"`
}

type CacheConfig struct {
	Persistent *PersistentCacheConfig `yaml:"persistent,omitempty"`
}

type RetryConfig struct {
	MaxRetries int    `yaml:"max-retries"`
	BaseDelay  string `yaml:"base-delay"`
	MaxDelay   string `yaml:"max-delay"`
}

type AgentConfig struct {
	Infisical InfisicalConfig `yaml:"infisical"`
	Sinks     []Sink          `yaml:"sinks"`
	Templates []Template      `yaml:"templates"`
	Auth      AuthConfig      `yaml:"auth"`
	Cache     CacheConfig     `yaml:"cache,omitempty"`
}

type ConfigMap struct {
	Infisical struct {
		Address                     string `yaml:"address"`
		RevokeCredentialsOnShutdown bool   `yaml:"revoke-credentials-on-shutdown"`
		Auth                        struct {
			Type   string                 `yaml:"type"` // Supported types: kubernetes, ldap-auth, aws-iam
			Config map[string]interface{} `yaml:"config"`
		} `yaml:"auth"`
		RetryConfig *RetryConfig `yaml:"retry-strategy,omitempty"`
	} `yaml:"infisical"`
	Templates []Template  `yaml:"templates"`
	Cache     CacheConfig `yaml:"cache,omitempty"`
}

type StartupScriptTemplateData struct {
	ExitAfterAuth  bool
	TimeoutSeconds int
}

package agent

import (
	"encoding/json"
	"strings"

	"github.com/Infisical/infisical-agent-injector/pkg/util"
	jsonpatch "github.com/evanphx/json-patch"
	corev1 "k8s.io/api/core/v1"
)

func toRawJSON(v interface{}) json.RawMessage {
	b, _ := json.Marshal(v)
	return json.RawMessage(b)
}

func AddOp(path string, value interface{}) jsonpatch.Operation {
	pathRaw, valueRaw := toRawJSON(path), toRawJSON(value)

	return map[string]*json.RawMessage{
		"op":    &util.PatchOperationAdd,
		"path":  &pathRaw,
		"value": &valueRaw,
	}
}

func RemoveOp(path string) jsonpatch.Operation {
	pathRaw := toRawJSON(path)
	return map[string]*json.RawMessage{
		"op":   &util.PatchOperationRemove,
		"path": &pathRaw,
	}
}

// addResourcesWithPath is a generic function that handles adding both volumes and volume mounts
func addResourcesWithPath[T any](existing []T, newItems []T, basePath string) jsonpatch.Patch {
	var patches jsonpatch.Patch

	if len(existing) == 0 && len(newItems) > 0 {
		// if there are no existing items, add them all at once as an array
		patches = append(patches, AddOp(basePath, newItems))
		return patches
	}

	// add each item individually to the end of the array
	for _, item := range newItems {
		patches = append(patches, AddOp(basePath+"/-", item))
	}

	return patches
}

func addVolumes(target []corev1.Volume, volumes []corev1.Volume, base string) jsonpatch.Patch {
	return addResourcesWithPath(target, volumes, base)
}

func addVolumeMounts(target []corev1.VolumeMount, mounts []corev1.VolumeMount, base string) jsonpatch.Patch {
	return addResourcesWithPath(target, mounts, base)
}
func removeContainers(path string) jsonpatch.Patch {
	return []jsonpatch.Operation{RemoveOp(path)}
}

func addContainers(target []corev1.Container, containers []corev1.Container, base string) jsonpatch.Patch {
	if len(target) == 0 && len(containers) > 0 {
		return []jsonpatch.Operation{AddOp(base, containers)}
	}

	var patches jsonpatch.Patch
	for _, container := range containers {
		patches = append(patches, AddOp(base+"/-", container))
	}
	return patches
}

func updatePodAnnotations(target map[string]string, annotations map[string]string) jsonpatch.Patch {
	var result jsonpatch.Patch
	if len(target) == 0 {
		return []jsonpatch.Operation{AddOp("/metadata/annotations", annotations)}
	}

	for key, value := range annotations {
		escapedKey := strings.NewReplacer("~", "~0", "/", "~1").Replace(key)

		result = append(result, AddOp("/metadata/annotations/"+escapedKey, value))
	}

	return result
}

